const ctF = (n) => `${n} ct`;
// Teile einer geführten Sachaufgabe.
export const ANGABEN = (wichtig, unwichtig, text = 'Welche Angaben brauchst du für die Rechnung?') => teilWahl('angaben', text, [...wichtig.map((t) => opt(t, true)), ...unwichtig.map((t) => opt(t, false, 'sach-unnoetige-angabe'))], true);
export const RECHNUNG = (richtig, falsch, text = 'Welche Rechnung passt?') => teilWahl('rechnung', text, [opt(richtig, true), ...falsch.map((t) => opt(t, false, 'sach-falsche-rechnung'))]);
export const ANTWORT = (richtig, falsch, text = 'Welcher Antwortsatz passt zur Frage?') => teilWahl('antwort', text, [opt(richtig, true), ...falsch.map((t) => opt(t, false, 'sach-frage-verfehlt'))]);
